/**
 * Validates `app/data/price_forecast.json` before it ships.
 *
 * The file is generated by `chicken_price_forecast/src/09_export_frontend.py`.
 * This check is the thing that fails loudly if someone hand-edits the JSON, if
 * the export is stale relative to the calendar, or if the three forecast
 * columns stop agreeing with each other.
 *
 *   node scripts/validate_price_forecast.mjs
 */
import { readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, '..');

const read = (path) => JSON.parse(readFileSync(resolve(root, path), 'utf8'));

const forecast = read('app/data/price_forecast.json');
const events = read('app/data/up_chicken_events.json');

const failures = [];
const fail = (message) => failures.push(message);

const DAY_MS = 86_400_000;
const epoch = (iso) => {
    const [y, m, d] = iso.split('-').map(Number);
    return Date.UTC(y, m - 1, d);
};

const { meta, daily, events: eventRows, eventForecasts } = forecast;

// ---- shape -----------------------------------------------------------------
if (!meta || !Array.isArray(daily) || !Array.isArray(eventRows) || !Array.isArray(eventForecasts)) {
    fail('missing meta, daily, events or eventForecasts');
} else {
    // ---- coverage ----------------------------------------------------------
    if (daily.length === 0) {
        fail('daily forecast is empty');
    } else {
        const first = daily[0].date;
        const last = daily[daily.length - 1].date;
        const expected = Math.round((epoch(last) - epoch(first)) / DAY_MS) + 1;

        if (daily.length !== expected) {
            fail(`daily rows are not contiguous: ${daily.length} rows for ${expected} calendar days`);
        }
        if (first !== meta.forecastStart) fail(`first row ${first} ≠ meta.forecastStart ${meta.forecastStart}`);
        if (last !== meta.forecastEnd) fail(`last row ${last} ≠ meta.forecastEnd ${meta.forecastEnd}`);
        if (meta.forecastEnd !== '2027-12-31') fail(`horizon ends ${meta.forecastEnd}, expected 2027-12-31`);
        if (meta.forecastStart <= meta.dataThrough) {
            fail(`forecast starts ${meta.forecastStart}, not after data through ${meta.dataThrough}`);
        }

        for (const row of daily) {
            if (!(row.lo95 <= row.lo80 && row.lo80 <= row.forecast && row.forecast <= row.hi80 && row.hi80 <= row.hi95)) {
                fail(`interval ordering broken on ${row.date}`);
                break;
            }
            const rebuilt = row.baseline * (1 + row.impactPct / 100);
            if (Math.abs(rebuilt - row.forecast) > 0.15) {
                fail(`forecast ≠ baseline × (1 + impact) on ${row.date}: ${rebuilt} vs ${row.forecast}`);
                break;
            }
        }
    }

    // ---- event references --------------------------------------------------
    const known = new Set(eventRows.map((row) => row.id));
    const unknown = new Set();
    for (const row of daily) for (const id of row.events) if (!known.has(id)) unknown.add(id);
    if (unknown.size > 0) fail(`daily rows reference unknown events: ${[...unknown].join(', ')}`);

    // ---- event forecasts ---------------------------------------------------
    const definitionIds = new Set(events.definitions.map((definition) => definition.id));
    const regime = new Set(eventRows.filter((row) => row.category === 'seasonal').map((row) => row.id));
    for (const row of eventForecasts) {
        const overlapsHorizon = row.start <= meta.forecastEnd && row.end >= meta.forecastStart;
        if (!overlapsHorizon) fail(`event forecast ${row.id} ${row.start} falls outside the horizon`);
        if (!definitionIds.has(row.id)) fail(`event forecast references unknown definition ${row.id}`);
        if (regime.has(row.id)) fail(`regime event ${row.id} should not be forecast as a discrete effect`);
        if (row.occurrences === 0 && row.reliability !== 'E') {
            fail(`${row.id} has no historical occurrences but grade ${row.reliability}, expected E`);
        }
    }

    const missing = [...definitionIds].filter(
        (id) => !regime.has(id) && eventRows.some((row) => row.id === id) && !eventForecasts.some((row) => row.id === id),
    );
    if (missing.length > 0) fail(`event types with no future occurrence: ${missing.join(', ')}`);

    // ---- backtest block ----------------------------------------------------
    const bt = meta.backtest;
    if (!bt || !(bt.smape1to7 > 0) || !(bt.smape29to90 > 0)) fail('backtest summary missing or zero');
    if (daily.length > 0 && bt.scoredDays < 300) fail(`only ${bt.scoredDays} backtest days scored`);
}

if (failures.length > 0) {
    console.error(`price_forecast.json failed ${failures.length} check(s):`);
    for (const message of failures) console.error(`  - ${message}`);
    process.exit(1);
}

console.log(
    `price_forecast.json ok: ${daily.length} days (${meta.forecastStart} → ${meta.forecastEnd}), `
    + `${eventRows.length} event estimates, ${eventForecasts.length} future occurrences, `
    + `in-sample ${meta.dataThrough}.`,
);
